// Moore state machine, one-hot output for each state. All outputs are
// combinational functions of the current state and inputs.
module TopModule(input  clk, input  areset, input  bump_left, input  bump_right, input  ground, input  dig, output reg walk_left, output reg walk_right, output reg aaah, output reg digging);
    reg [2:0] state, next_state;
    reg [23:0] fall_timer;
    always @(*) begin
        case (state)
            3'b000: begin walk_left = 1; walk_right = 0; aaah = 0; digging = 0; next_state = bump_left ? 3'b001 : (bump_right ? 3'b010 : (ground ? 3'b000 : 3'b100)); end
            3'b001: begin walk_left = 0; walk_right = 1; aaah = 0; digging = 0; next_state = bump_left ? 3'b001 : (bump_right ? 3'b010 : (ground ? 3'b000 : 3'b100)); end
            3'b010: begin walk_left = 1; walk_right = 0; aaah = 0; digging = 0; next_state = bump_left ? 3'b001 : (bump_right ? 3'b010 : (ground ? 3'b000 : 3'b100)); end
            3'b100: begin walk_left = 0; walk_right = 0; aaah = ground ? 1 : 0; digging = 0; fall_timer = fall_timer + 1; next_state = bump_left ? 3'b001 : (bump_right ? 3'b010 : (dig ? 3'b011 : (fall_timer < 24 ? 3'b100 : (ground ? 3'b000 : 3'b101)))); end
            3'b011: begin walk_left = 1; walk_right = 0; aaah = 0; digging = 1; next_state = ground ? 3'b000 : 3'b011; end
            3'b101: begin walk_left = 1; walk_right = 0; aaah = 1; digging = 0; next_state = 3'b000; end
        endcase
    end
    always @(posedge clk) begin
        if (areset) state <= 3'b000;
        else state <= next_state;
    end
    always @(posedge clk) begin
        if (state == 3'b101) fall_timer <= 0;
    end
endmodule

// Moore state machine, one register + combinational logic = FSM.
module TopModule(
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);
    reg [1:0] state, next_state;
    reg [23:0] fall_counter;
    always @(posedge clk) begin
        if (areset) begin
            state <= 2'b00;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
            fall_counter <= 0;
        end else begin
            state <= next_state;
            case (state)
                2'b00: begin // walking left
                    walk_left <= 1;
                    walk_right <= 0;
                    if (bump_left) next_state = 2'b01;
                    else if (ground) next_state = 2'b00;
                    else if (fall_counter == 24'd20) next_state = 2'b10;
                    else begin
                        next_state = 2'b00;
                        fall_counter <= fall_counter + 1;
                        aaah <= 1;
                    end
                end
                2'b01: begin // walking right
                    walk_left <= 0;
                    walk_right <= 1;
                    if (bump_right) next_state = 2'b00;
                    else if (ground) next_state = 2'b01;
                    else if (fall_counter == 24'd20) next_state = 2'b10;
                    else begin
                        next_state = 2'b01;
                        fall_counter <= fall_counter + 1;
                        aaah <= 1;
                    end
                end
                2'b10: begin // falling
                    walk_left <= 0;
                    walk_right <= 0;
                    aaah <= 1;
                    if (ground) begin
                        if (dig) next_state = 2'b11;
                        else next_state = 2'b00;
                        fall_counter <= 0;
                    end
                end
                2'b11: begin // digging
                    walk_left <= 0;
                    walk_right <= 0;
                    aaah <= 0;
                    digging <= 1;
                    if (ground) begin
                        next_state = 2'b00;
                        fall_counter <= 0;
                    end
                end
            endcase
        end
    end
endmodule

